import { NextRequest } from 'next/server';
import { getStreamUrl, invalidateStreamUrl } from '@/lib/ytdlp';
import { request as undiciRequest } from 'undici';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

interface CachedAudio {
  buffer: Buffer;
  contentType: string;
  expires: number;
}

const globalWithAudioCache = global as typeof globalThis & {
  _audioBufferCache?: Map<string, CachedAudio>;
};

if (!globalWithAudioCache._audioBufferCache) {
  globalWithAudioCache._audioBufferCache = new Map();
}

const audioCache = globalWithAudioCache._audioBufferCache;

export async function OPTIONS() {
  return new Response(null, {
    status: 204,
    headers: {
      'Access-Control-Allow-Origin': '*',
      'Access-Control-Allow-Methods': 'GET, HEAD, OPTIONS',
      'Access-Control-Allow-Headers': 'Range, Content-Type, Accept',
      'Access-Control-Expose-Headers': 'Content-Range, Content-Length, Accept-Ranges',
      'Access-Control-Max-Age': '86400',
    },
  });
}

export async function HEAD(req: NextRequest) {
  const { searchParams } = new URL(req.url);
  const videoId = searchParams.get('videoId');

  if (!videoId) {
    return new Response(null, { status: 400 });
  }

  try {
    const cached = audioCache.get(videoId);
    let totalLength = cached?.buffer.length;
    let contentType = cached?.contentType || 'audio/mp4';

    if (!totalLength) {
      const audioUrl = await getStreamUrl(videoId);
      const upstreamResp = await undiciRequest(audioUrl, {
        method: 'HEAD',
        headers: {
          'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36',
          'Referer': 'https://www.youtube.com/',
          'Origin': 'https://www.youtube.com',
        },
      });
      totalLength = parseInt(upstreamResp.headers['content-length'] as string, 10) || 0;
      contentType = (upstreamResp.headers['content-type'] as string) || 'audio/mp4';
    }

    const headers = new Headers();
    headers.set('Content-Type', contentType);
    headers.set('Accept-Ranges', 'bytes');
    if (totalLength) headers.set('Content-Length', totalLength.toString());
    headers.set('Access-Control-Allow-Origin', '*');
    headers.set('Access-Control-Expose-Headers', 'Content-Range, Content-Length, Accept-Ranges');

    return new Response(null, { status: 200, headers });
  } catch {
    return new Response(null, { status: 500 });
  }
}

export async function GET(req: NextRequest) {
  const { searchParams } = new URL(req.url);
  const videoId = searchParams.get('videoId');

  if (!videoId) {
    return new Response(JSON.stringify({ error: 'Missing videoId' }), {
      status: 400,
      headers: {
        'Content-Type': 'application/json',
        'Access-Control-Allow-Origin': '*',
      },
    });
  }

  try {
    let cached = audioCache.get(videoId);

    if (!cached || cached.expires < Date.now()) {
      let audioUrl = await getStreamUrl(videoId);

      const requestHeaders: Record<string, string> = {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36',
        'Referer': 'https://www.youtube.com/',
        'Origin': 'https://www.youtube.com',
      };

      let upstreamResp = await undiciRequest(audioUrl, { headers: requestHeaders });

      // If upstream URL returned 403 (expired or invalid token), invalidate cache and re-extract once
      if (upstreamResp.statusCode === 403) {
        console.warn(`[Stream] 403 from upstream for ${videoId}, invalidating cache and re-extracting...`);
        invalidateStreamUrl(videoId);
        audioUrl = await getStreamUrl(videoId);
        upstreamResp = await undiciRequest(audioUrl, { headers: requestHeaders });
      }

      if (upstreamResp.statusCode >= 400) {
        invalidateStreamUrl(videoId);
        throw new Error(`Upstream returned HTTP ${upstreamResp.statusCode}`);
      }

      const contentType = (upstreamResp.headers['content-type'] as string) || 'audio/mp4';
      const arrayBuf = await upstreamResp.body.arrayBuffer();
      const buffer = Buffer.from(arrayBuf);

      if (audioCache.size > 25) {
        const oldestKey = audioCache.keys().next().value;
        if (oldestKey) audioCache.delete(oldestKey);
      }

      cached = {
        buffer,
        contentType,
        expires: Date.now() + 60 * 60 * 1000,
      };
      audioCache.set(videoId, cached);
    }

    const { buffer, contentType } = cached;
    const totalSize = buffer.length;
    const rangeHeader = req.headers.get('range');

    const responseHeaders = new Headers();
    responseHeaders.set('Content-Type', contentType);
    responseHeaders.set('Accept-Ranges', 'bytes');
    responseHeaders.set('Cache-Control', 'public, max-age=3600');
    responseHeaders.set('Access-Control-Allow-Origin', '*');
    responseHeaders.set('Access-Control-Allow-Methods', 'GET, HEAD, OPTIONS');
    responseHeaders.set('Access-Control-Allow-Headers', 'Range, Content-Type, Accept');
    responseHeaders.set('Access-Control-Expose-Headers', 'Content-Range, Content-Length, Accept-Ranges');

    // Handle Range Requests (HTTP 206 Partial Content)
    if (rangeHeader) {
      const parts = rangeHeader.replace(/bytes=/, '').split('-');
      const start = parseInt(parts[0], 10) || 0;
      const end = parts[1] ? Math.min(parseInt(parts[1], 10), totalSize - 1) : totalSize - 1;

      if (start >= totalSize || end < start) {
        responseHeaders.set('Content-Range', `bytes */${totalSize}`);
        return new Response(null, { status: 416, headers: responseHeaders });
      }

      const slice = buffer.subarray(start, end + 1);
      responseHeaders.set('Content-Range', `bytes ${start}-${end}/${totalSize}`);
      responseHeaders.set('Content-Length', slice.length.toString());

      return new Response(new Uint8Array(slice), {
        status: 206,
        headers: responseHeaders,
      });
    }

    // Full File Response (HTTP 200 OK)
    responseHeaders.set('Content-Length', totalSize.toString());
    return new Response(new Uint8Array(buffer), {
      status: 200,
      headers: responseHeaders,
    });
  } catch (err: any) {
    const errMsg = err?.message || 'Stream error';
    console.error('[API Stream Error]:', errMsg);

    const isUnavailable = errMsg.includes('TRACK_UNAVAILABLE') || errMsg.includes('unavailable');
    const statusCode = isUnavailable ? 404 : 500;

    return new Response(
      JSON.stringify({
        error: isUnavailable ? 'Track unavailable' : 'Stream error',
        message: errMsg,
      }),
      {
        status: statusCode,
        headers: {
          'Content-Type': 'application/json',
          'Access-Control-Allow-Origin': '*',
        },
      }
    );
  }
}
